$d = 'E:\site\IDM\searches'; $files = @('driver-di32','driver-di64','driver-f32','driver-f64'); foreach ($n in $files) { $file = "$d\$n.json"; $j = Get-Content $file -Raw | ConvertFrom-Json; $nru = $j.data.normalized_result; if (-not $j.ok) { "=== $n === NOT OK: " + $j | ConvertTo-Json -Compress -Depth 2 | ForEach-Object { $_.Substring(0, [Math]::Min(1600, $_.Length)) } } else { "=== $n === ev: " + $j.evidence_id; $nru | ConvertTo-Json -Compress -Depth 2 | ForEach-Object { $_.Substring(0, [Math]::Min(1600, $_.Length)) } } }